String s = "aabb";
Map<Character, Integer> f = new HashMap<>();
for (char c : s.toCharArray()) f.merge(c, 1, Integer::sum);
System.out.println(f.get('a') + " " + f.size());

String s = "abba";
Set<Character> seen = new HashSet<>();
for (int i = 0; i < s.length(); i++) {
    char c = s.charAt(i);
    if (!seen.add(c)) { System.out.println(c); break; }
}

Map<Integer, Integer> m = new HashMap<>();
for (int i = 1; i <= 3; i++) m.put(i, i);
for (int k : m.keySet()) {
    m.remove(k);
}
System.out.println(m.size());

int[] a = {2, 7, 11, 15};
int target = 9;
Map<Integer, Integer> seen = new HashMap<>();
for (int i = 0; i < a.length; i++) {
    if (seen.containsKey(target - a[i])) {
        System.out.println(seen.get(target - a[i]) + "," + i);
        break;
    }
    seen.put(a[i], i);
}

